using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Reflection;using System.Windows.Forms;using Frociart;
internal static class CommentTests {
 static int checks;static string root;
 static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;}
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static void Pump(int ms){var s=System.Diagnostics.Stopwatch.StartNew();while(s.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(5);}}
 static string Run(Diagram d){var r=new Interpreter(d);for(int i=0;i<500&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Execution completes: "+r.Error);return String.Join("|",r.Output);}
 static void Reject(string s){bool rejected=false;try{FlowPseudocode.Decode(s);}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid note rejected");}
 static string Notes(Diagram d){return String.Join("|",d.Nodes.Select(n=>n.Comment??"").Where(x=>x.Length>0).OrderBy(x=>x,StringComparer.Ordinal));}
 [STAThread]static int Main(string[] args){try{root=args[0];Directory.CreateDirectory(root);
  var legacy=FlowPseudocode.Decode("INIZIO\nx=2\nSE x > 0 ALLORA\nSTAMPA x\nALTRIMENTI\nSTAMPA 0\nFINE SE\nFINE");
  Check(!Encoding.UTF8.GetString(DiagramIO.EncodeDocument(legacy)).Contains("Comment"),"Legacy output omits optional field");
  string note="Testo: è 🐢\n\"virgolette\" <tag> & // nota \\u000a \\u0022 */ \\n";
  for(int i=0;i<legacy.Nodes.Count;i++)legacy.Nodes[i].Comment=note+" #"+i;
  string before=Convert.ToBase64String(DiagramIO.EncodeDocument(legacy));Check(Run(legacy)=="2","Notes never execute");
  var clone=DiagramIO.Clone(legacy);Check(Notes(clone)==Notes(legacy)&&clone.Nodes.All(n=>n.PreviewComment==null),"Deep clone keeps committed notes");
  Check(Notes(FlowClipboard.Decode(FlowClipboard.Encode(legacy)))==Notes(legacy),"Clipboard byte codec keeps notes without reading clipboard");
  DiagramIO.Save(Path.Combine(root,"pc-comments.frociart"),legacy);Check(Notes(DiagramIO.Load(Path.Combine(root,"pc-comments.frociart")))==Notes(legacy),"Actual file save/reopen");
  string code=FlowPseudocode.Encode(legacy);File.WriteAllText(Path.Combine(root,"pc-comments.txt"),code);var round=FlowPseudocode.Decode(code);Check(Notes(round)==Notes(legacy)&&Run(round)=="2","Structured pseudocode preserves all annotations");
  var implicitStart=FlowPseudocode.Decode("NOTA \"operazione\"\nx=1\nSTAMPA x");Check(implicitStart.Nodes.First(n=>n.Kind==NodeKind.Process).Comment=="operazione"&&implicitStart.Nodes.First(n=>n.Kind==NodeKind.Start).Comment==null,"Implicit Start does not steal note");
  foreach(var invalid in new[]{"NOTA \"senza blocco\"","NOTA x\nx=1","NOTA \"a\"+\"b\"\nx=1","NOTA \"a\"\nFUNZIONE f()\nFINE FUNZIONE\nSTAMPA 1","SE vero ALLORA\nNOTA \"a\"\nFINE SE\nFINE","NOTA \""+new string('x',2049)+"\"\nx=1"})Reject(invalid);
  var combined=FlowPseudocode.Decode("INIZIO\nNOTA \"a\"\nNOTA \"b\"\nx=1\nFINE");Check(combined.Nodes.First(n=>n.Kind==NodeKind.Process).Comment=="a\nb","Consecutive notes combine");
  foreach(var sample in new[]{"INIZIO\nPER i DA 1 A 2 FAI\nSTAMPA i\nFINE PER\nFINE","INIZIO\nx=0\nMENTRE x < 2 FAI\nx=x+1\nFINE MENTRE\nSTAMPA x\nFINE","FUNZIONE doppio(n: INTERO) -> INTERO risultato\nrisultato=n*2\nFINE FUNZIONE\nINIZIO\nSTAMPA doppio(3)\nFINE"}){var d=FlowPseudocode.Decode(sample);foreach(var g in new[]{d}.Concat(d.Functions==null?Enumerable.Empty<Diagram>():d.Functions.Select(f=>f.Body)))for(int i=0;i<g.Nodes.Count;i++)g.Nodes[i].Comment="nota "+i;var q=FlowPseudocode.Decode(FlowPseudocode.Encode(d));Check(Notes(d)==Notes(q)&&Run(d)==Run(q),"Cycles/functions preserve notes and execution");if(d.Functions!=null)Check(Notes(d.Functions[0].Body)==Notes(q.Functions[0].Body),"Function note persistence");}
  var separate=DiagramIO.Clone(legacy);separate.Nodes.Add(new FlowNode{Kind=NodeKind.Process,Text="unused=1",Comment="scollegato"});Check(Notes(FlowPseudocode.Decode(FlowPseudocode.Encode(separate)))==Notes(separate),"Disconnected note retained in explicit paths");
  var program=FlowSource.Compile(legacy);legacy.Nodes[0].Comment="mutated";Check(program.Scopes[0].Blocks[0].Comment.StartsWith(note),"Source IR freezes note snapshot");var j=FlowJava.Generate(program,File.ReadAllText(Path.Combine(root,"../frociart-v1-capabilities/pc/Source/JavaRuntime.txt")),"CommentProgram");var py=FlowPython.Generate(program);Check(j.Text.Contains("// Nota")&&py.Text.Contains("# Nota"),"Java and Python contain safe source documentation");File.WriteAllText(Path.Combine(root,"CommentProgram.java"),j.Text,new UTF8Encoding(false));File.WriteAllText(Path.Combine(root,"comments.py"),py.Text,new UTF8Encoding(false));
  var measured=clone.Nodes.First(x=>x.Kind==NodeKind.Process);var size=FlowSizing.Size(measured);measured.Comment=null;Check(size.Height>FlowSizing.Size(measured).Height,"Notes enlarge block geometry");measured.Comment=new string('a',2049);bool limit=false;try{DiagramIO.EncodeDocument(clone);}catch(InvalidDataException){limit=true;}Check(limit,"Oversize note rejected by file codec");
  using(var main=new MainForm(null,true)){main.Show();Pump(100);var d=FlowPseudocode.Decode("INIZIO\nx=1\nSTAMPA x\nFINE");main.SetDocument(d,null,false);var node=d.Nodes.First(x=>x.Kind==NodeKind.Process);main.Canvas.SelectNode(node.Id);var comment=(TextBox)Get(main,"comment");Check(comment.Visible&&comment.MaxLength==2048,"Actual inspector exposes bounded note editor");comment.Text="Inizializza il contatore.\r\nIl valore verrà mostrato nel passaggio successivo.";Pump(85);Check(node.Comment==null&&node.PreviewComment==comment.Text.Replace("\r\n","\n"),"Live draft does not mutate saved note");main.CommitInspector();Pump(450);string committed=main.Document.Nodes.First(x=>x.Id==node.Id).Comment;Check(committed==comment.Text.Replace("\r\n","\n")&&node.PreviewComment==null,"Apply commits note and clears transient text");Check(Run(main.Document)=="1","Actual inspector comment leaves behavior intact");var dup=main.Canvas.DuplicateSelected();Check(dup.Comment==committed,"Native duplicate retains note");Call(main,"Undo");main.Canvas.SelectNode(node.Id);Call(main,"Undo");Check(main.Document.Nodes.First(x=>x.Id==node.Id).Comment==null,"One note undo restores prior state");Call(main,"Redo");Check(main.Document.Nodes.First(x=>x.Id==node.Id).Comment==committed,"Redo restores note");Pump(450);Check(comment.Text.Contains("\r\n"),"Android-style LF is shown as a real Windows edit newline");int history=((System.Collections.ICollection)Get(main,"undo")).Count;main.CommitInspector();Check(((System.Collections.ICollection)Get(main,"undo")).Count==history,"Opening LF note alone does not create an edit");
   DiagramExport.ExportSvg(main.Canvas,Path.Combine(root,"comments.svg"));Check(File.ReadAllText(Path.Combine(root,"comments.svg")).Contains("Nota:"),"Actual SVG export contains note");DiagramExport.ExportPng(main.Canvas,Path.Combine(root,"comments.png"));Check(new FileInfo(Path.Combine(root,"comments.png")).Length>1000,"Actual PNG export created");DiagramExport.ExportPdf(main.Canvas,Path.Combine(root,"comments.pdf"));Check(File.ReadAllText(Path.Combine(root,"comments.pdf")).StartsWith("%PDF"),"Actual PDF export created");
   using(var png=new Bitmap(main.Width,main.Height)){main.DrawToBitmap(png,new Rectangle(0,0,png.Width,png.Height));png.Save(Path.Combine(root,"desktop-comment-editor.png"));}
   main.SetDocument(new Diagram(),null,false);main.Close();}
  Check(before==Convert.ToBase64String(DiagramIO.EncodeDocument(DiagramIO.Load(Path.Combine(root,"pc-comments.frociart")))) ,"Original saved project intact");var android=DiagramIO.Load(Path.Combine(root,"android-comments.frociart"));Check(Notes(android)==Notes(DiagramIO.Load(Path.Combine(root,"pc-comments.frociart"))),"Android annotated file opens exactly on PC");Check(Notes(FlowPseudocode.Decode(File.ReadAllText(Path.Combine(root,"android-comments.txt"))))==Notes(android),"Android annotated pseudocode opens exactly on PC");Console.WriteLine("COMMENTS_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
